import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const rawPlan = localStorage.getItem('roadmapPlan');
    const selectedDomain = localStorage.getItem('selectedDomain') || name || 'blockchain';
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    if (rawPlan) {
      try {
        const parsedPlan = JSON.parse(rawPlan);
        if (Array.isArray(parsedPlan)) {
          setRoadmapPlan(parsedPlan);
        }
      } catch (e) {
        console.error("Local storage parsing error", e);
      }
    }
    setDomain(selectedDomain);
    setTimeline(savedTimeline);
  }, [name]);

  const handleStartLearning = () => navigate('/tasks');
  const getDomainTitle = () => domain.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  // 🛠️ FIX 1: Convert Timeline String to Numeric Days
  const getTimelineInDays = () => {
    if (!timeline) return 0;
    const numericValue = parseInt(timeline.match(/\d+/)); 
    return timeline.toLowerCase().includes('year') ? numericValue * 365 : numericValue * 30;
  };

  const totalDays = getTimelineInDays();
  const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
  const completedCount = completedDays.length;
  const remainingDays = Math.max(totalDays - completedCount, 0);

  const completionPercentage = totalDays > 0 ? Math.min(100, Math.round((completedCount / totalDays) * 100)) : 0;

  // Helper to find which days belong to which phase
  const getPhaseDayRange = (phaseIndex) => {
    const tasksPerDay = 4;
    let tasksBefore = 0;
    for (let i = 0; i < phaseIndex; i++) {
      if (roadmapPlan[i]) tasksBefore += roadmapPlan[i].length;
    }
    const startDay = Math.floor(tasksBefore / tasksPerDay) + 1;
    const phaseTotalDays = Math.ceil(roadmapPlan[phaseIndex].length / tasksPerDay);
    
    return { startDay, endDay: startDay + phaseTotalDays - 1 };
  };

  const getPhaseProgress = (phaseIndex, phaseTasks) => {
    const { startDay, endDay } = getPhaseDayRange(phaseIndex);
    const phaseTotalDays = (endDay - startDay) + 1;
    
    const completedInPhase = completedDays.filter(day => day >= startDay && day <= endDay).length;
    return Math.min(100, Math.round((completedInPhase / phaseTotalDays) * 100));
  };

  // 🛠️ FIX 2: Phase is only complete if ALL its days are in completedDays
  const isPhaseCompleted = (phaseIndex, phaseTasks) => {
    return getPhaseProgress(phaseIndex, phaseTasks) === 100;
  };

  const getCurrentPhaseIndex = () => {
    const tasksPerDay = 4;
    let tasksCovered = completedDays.length * tasksPerDay;
    let cumulativeTasks = 0;
    for (let i = 0; i < roadmapPlan.length; i++) {
      cumulativeTasks += roadmapPlan[i].length;
      if (tasksCovered < cumulativeTasks) return i;
    }
    return Math.max(0, roadmapPlan.length - 1);
  };

  const currentPhaseIndex = getCurrentPhaseIndex();

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
        <h1 className="text-4xl font-bold text-slate-900 dark:text-slate-50">{getDomainTitle()} Roadmap</h1>
        <p className="mt-3 text-lg text-slate-600 dark:text-slate-300">
          Your personalized {timeline} path with {roadmapPlan.length} phases
        </p>
        
        <div className="mt-6 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1">
            <p className="text-sm font-medium text-slate-700 dark:text-slate-300">Overall Progress</p>
            <ProgressBar label="Roadmap" value={completionPercentage} />
          </div>
          <div className="rounded-3xl bg-teal-100 p-5 dark:bg-slate-700">
            <p className="text-sm text-slate-700 dark:text-slate-300">Target Timeline</p>
            <p className="mt-2 text-2xl font-bold text-teal-900 dark:text-teal-200">{totalDays} Days</p>
          </div>
          <div className="rounded-3xl bg-orange-100 p-5 dark:bg-slate-700">
            <p className="text-sm text-slate-700 dark:text-slate-300">Days Remaining</p>
            <p className="mt-2 text-2xl font-bold text-orange-900 dark:text-orange-200">{remainingDays} / {totalDays}</p>
          </div>
        </div>
      </div>

      {/* Learning Phases */}
      <div className="rounded-[2rem] border border-slate-300 bg-white p-8 shadow-lg dark:border-slate-600 dark:bg-slate-800">
        <h2 className="text-2xl font-semibold mb-6">📚 Learning Phases</h2>
        <div className="space-y-4">
          {roadmapPlan.map((phase, index) => (
            <div 
              key={index} 
              className={`rounded-3xl border p-6 transition-all duration-300 ${
                isPhaseCompleted(index, phase) 
                ? "border-green-400 bg-green-50 dark:bg-green-900/10" 
                : index === currentPhaseIndex 
                ? "border-teal-400 bg-blue-50 shadow-md scale-[1.01]" 
                : "border-slate-200 bg-slate-50"
              }`}
            >
              <div className="flex items-center gap-4">
                <span className={`h-10 w-10 flex items-center justify-center rounded-full font-bold text-white ${isPhaseCompleted(index, phase) ? 'bg-green-500' : 'bg-teal-500'}`}>
                  {isPhaseCompleted(index, phase) ? '✓' : index + 1}
                </span>
                <div className="flex-1">
                  <div className="flex justify-between items-center mb-2">
                    <h3 className="font-bold text-slate-900 dark:text-slate-50">
                      Phase {index + 1} {index === currentPhaseIndex && !isPhaseCompleted(index, phase) && "📍"}
                    </h3>
                    <span className="text-xs font-bold text-slate-500">{getPhaseProgress(index, phase)}%</span>
                  </div>
                  <ProgressBar label={`Phase ${index + 1}`} value={getPhaseProgress(index, phase)} />
                </div>
              </div>
              <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
                {phase.slice(0, 4).map((task, tIdx) => (
                  <div key={tIdx} className="rounded-xl bg-white p-3 text-sm shadow-sm border border-slate-100">
                    <span className="text-teal-500 mr-2">●</span>{task}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex justify-center pb-10">
        <Button onClick={handleStartLearning} className="px-10 py-4 text-xl">Continue Learning Journey 🚀</Button>
      </div>
    </div>
  );
}
